draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  for (let i = 0; i < 10; i++) {
    ctx.moveTo(W / 2 + Math.sin(t + i) * 100, H / 2 + Math.cos(t + i) * 100);
    ctx.lineTo(W / 2 + Math.sin(t + i + Math.PI / 2) * 50, H / 2 + Math.cos(t + i + Math.PI / 2) * 50);
  }
  ctx.stroke();
  ctx.restore();
}
